#!/usr/bin/env python3
"""Make results/INDEX.md and registry/COVERAGE.md from REGISTRY.json. Do not edit those two files by hand. 25 Oct 2026.
Usage: python3 make_index.py"""
import collections, json, re
from pathlib import Path
HERE = Path(__file__).resolve().parent
WORK = HERE.parent
R = json.load(open(HERE / "REGISTRY.json"))
B = json.load(open(HERE / "backfill_report.json"))
C = json.load(open(HERE / "coverage_files.json"))
ST = list(R["status_values"])
E = R["entries"]
mods = R["modules"]


def cell(s):
    return (s or "").replace("|", "/").replace("\n", " ")[:160]


HXI = HERE / "data_homes" / "exchange_inventory_hydroacoustics.json.gz"
if HXI.exists():
    import gzip
    _h = json.load(gzip.open(HXI, "rt"))
    HX = (f"inventory {_h['built_utc']}, {_h['n_files']} files, {_h['bytes']} bytes; SHA-256 from SHA256SUMS {_h['n_sha_from_sums']}, "
          f"computed {_h['n_hashed_now']}, not hashed {_h['n_not_hashed']}")
else:
    HX = "no inventory"
PAF = HERE / "modules" / "hydroacoustics" / "platform_artifacts.tsv"
if PAF.exists():
    _r = [l.split("\t") for l in PAF.read_text().splitlines()[1:]]
    _c = collections.Counter((x[0], x[-1] != "no copy") for x in _r)
    PA = (f"`modules/hydroacoustics/platform_artifacts.tsv` lists the {len(_r)} latest artifact versions of the three hydro threads of 23-25 Oct 2026: "
          + "; ".join(f"{t}: {_c[(t, True)]} with a registered copy, {_c[(t, False)]} with no copy" for t in sorted({x[0] for x in _r}))
          + ". An artifact with no copy is not registered.")
else:
    PA = ""
lines = ["# Results index", "",
         "Generated by `registry/make_index.py` from `registry/REGISTRY.json`. Do not edit this file by hand.",
         f"Registry built {R['built_utc']}; working-branch head at build: `{R['work_branch_head_at_build'][:12]}`.", "",
         "Use the registry id when you quote a number. A status is from existing records only (no new audit). "
         "UNCHECKED means: not yet used in a result that we quote. Check an item when you use it.", "",
         "Hydroacoustics results are in this index as module `hydroacoustics` (phase 2, 26 Oct 2026; ids `hydro.<hydro id>`). "
         "The hydroacoustics registry on branch `hypothesis/hydroacoustics` stays the module's own record; `results/hydroacoustics/INDEX.md` "
         "is generated from it and also lists its constants and defects.", ""]
for m in mods:
    rs = sorted((e for e in E if e["module"] == m and e["path"].startswith("WORK:results/")), key=lambda e: e["path"])
    if not rs:
        continue
    cnt = collections.Counter(e["status"] for e in rs)
    lines += [f"## {m} ({len(rs)} items)", "", "Status: " + ", ".join(f"{s} {cnt[s]}" for s in ST if cnt[s]), "",
              "| registry id | path under results/ | status | superseded by | description |", "|---|---|---|---|---|"]
    for e in rs:
        lines.append(f"| `{e['id']}` | {cell(e['path'][len('WORK:results/'):])} | {e['status']} | {('`' + e['superseded_by'] + '`') if e.get('superseded_by') else ''} | {cell(e.get('note'))} |")
    lines.append("")
XD = sorted((e for e in E if e["path"].startswith("XDRIVE:")), key=lambda e: e["path"])
lines += ["## Files held on the external drive - ask Pete", "",
          "These items are not on the Mac. Sessions cannot read the drive. To use one, ask Pete to copy it back to "
          "`~/Downloads/mh370-exchange/`, then check each file against the SHA-256 in the registry manifest. "
          "Do not take an item as lost because it is not on the Mac: look here and in the registry first.", "",
          "| registry id | path on the drive | holder | status | files | description |", "|---|---|---|---|---|---|"]
for e in XD:
    lines.append(f"| `{e['id']}` | {cell(e['path'][len('XDRIVE:'):]) or '(drive folder)'} | held on external drive - ask Pete ({cell(e.get('holder') or '')}) | "
                 f"{e['status']} | {e.get('n_files') if e.get('n_files') is not None else '-'} | {cell(e.get('note'))} |")
lines.append("")
(WORK / "results" / "INDEX.md").write_text("\n".join(lines) + "\n")

# coverage report
cv = ["# Registry coverage report", "", "Generated by `registry/make_index.py`. Do not edit this file by hand.", f"Registry built {R['built_utc']}.", "",
      "## Entries for each module and status", "", "| module | " + " | ".join(ST) + " | total |", "|---|" + "---|" * (len(ST) + 1)]
tot = collections.Counter()
for m in mods:
    c = collections.Counter(e["status"] for e in E if e["module"] == m); tot.update(c)
    cv.append(f"| {m} | " + " | ".join(str(c[s]) for s in ST) + f" | {sum(c.values())} |")
cv.append("| all | " + " | ".join(str(tot[s]) for s in ST) + f" | {sum(tot.values())} |")
cv += ["", "## Entries for each kind", "", "| kind | entries |", "|---|---|"]
for k, n in sorted(collections.Counter(e["kind"] for e in E).items()):
    cv.append(f"| {k} | {n} |")
rank = collections.Counter(e["status_rank"] for e in E)
cv += ["", "## Source of each status", "", "| source | entries |", "|---|---|"] + [f"| {k} | {v} |" for k, v in sorted(rank.items())]
ri = B["results_items"]
cv += ["", "## results/ coverage", "",
       f"- Folders under results/: {ri['folders_total']}. Loose files at the top of results/: {ri['loose_total']}.",
       f"- Registered in phase 1: {ri['registered_results_items']} items. Left for phase 2 (hydroacoustics): {ri['hydro_items']} items. "
       f"Phase 2 (26 Oct 2026): {sum(1 for e in E if e['module'] == 'hydroacoustics' and e['path'].startswith('WORK:results/'))} hydroacoustics entries under results/ "
       f"cover these items (some items are split into sub-folders; see the table of files that are not registered).",
       f"- Tracked files on the branch: {C['tracked']}. Files in a manifest of this registry: {C['covered']}.", ""]
ex = [e for e in E if e["path"].startswith("EX:") and e.get("manifest")]
nh = sum(len(e.get("not_hashed", [])) for e in ex)
cv += ["## Exchange folder", "", f"- Entries: {len(ex)}. Files: {sum(e['n_files'] for e in ex)}. Bytes: {sum(e['bytes'] for e in ex)}.",
       f"- Files with no SHA-256 (1 GB or more and no SHA256SUMS entry): {nh}. List: " + ", ".join(f"`{x}`" for e in ex for x in e.get("not_hashed", [])), "",
       "- The hydroacoustics part of the exchange folder is in this registry since phase 2 (26 Oct 2026): " + HX + ".",
       "- Memory records say that `end-of-flight/run-i` and `end-of-flight/run-i-c2aim` are superseded by `run-i-dive`. These folders are not in the exchange folder now, so they have no entry.", ""]
cv += ["## Files that are not registered, and why", "", "| file | reason |", "|---|---|"]
for p in C["not_covered"]:
    why = "hydroacoustics: no hydro entry matches this file" if re.search(r"(?i)hydro", p) and not p.startswith("Claude Science Project Sep 29/registry/") else ("registry's own file (scripts, manifests, generated outputs); a registry does not list itself" if p.startswith("Claude Science Project Sep 29/registry/") else ("archive folder manifest note (described by project.note.archive-sep29-manifest)" if p.startswith("Archive Sep 29") else "not matched by an entry rule"))
    cv.append(f"| {cell(p)} | {why} |")
cv += ["", "## Status statements found but not applied", "",
       "These records name an item and a status word, but the statement is about another item. They are listed for review.", "",
       "| entry | source | statement |", "|---|---|---|"] + [f"| `{a}` | {b} | {cell(c)} |" for a, b, c in B.get("statements_not_applied", [])]
cv += ["", "## Name chains with a later date, not applied", "",
       "A later date can be a continuation, not a replacement. These keep their own status.", ""] + [f"- {', '.join('`' + x + '`' for x in g)}" for g in B.get("date_chains_not_applied", [])]
cv += ["", "## Hydroacoustics items left by phase 1 (registered in phase 2, 26 Oct 2026)", ""] + [f"- {k}: {len(B.get(k, []))}" for k in
       ("results_hydro_left_for_phase2", "coordination_hydro_left_for_phase2", "threads_hydro_left_for_phase2", "xdrive_hydro_left_for_phase2")]
H2 = [e for e in E if e["module"] == "hydroacoustics"]
cv += ["", "## Hydroacoustics phase 2: limits", "",
       f"- Entries: {len(H2)}. By root: " + ", ".join(f"{k} {v}" for k, v in sorted(collections.Counter(e['path'].split(':')[0] for e in H2).items())) + ".",
       "- GIT entries are files of branch `hypothesis/hydroacoustics` at the commit in the path; each blob is hashed (SHA-256).",
       f"- DL entries (data homes in ~/Downloads): files with no SHA-256 (1 GB or more and no SHA256SUMS entry): {sum(len(e.get('not_hashed', [])) for e in H2 if e['path'].startswith('DL:'))}. List: "
       + ", ".join(f"`{x}`" for e in H2 if e['path'].startswith('DL:') for x in e.get('not_hashed', [])),
       f"- XDRIVE entries: {sum(1 for e in H2 if e['path'].startswith('XDRIVE:'))}, listed from archive-tools item lists; the drive was not mounted, so the copies are not confirmed and not hashed.",
       "- `project.archive.hydroacoustic-handover` (phase 1) stays the one archive entry of `Hydroacoustic Handover/`; it is not repeated in module hydroacoustics.",
       "- Platform artifacts are not registry items: the roots do not include the artifact store. " + PA, ""]
MC = HERE / "modules" / "hydroacoustics" / "merge_check.json"
if MC.exists():
    _m = json.load(open(MC))
    cv += ["## Hydroacoustics phase 2: project build against the hydro build", "",
           f"`check_hydro_merge.py` compares, for each of the {_m['entries']} entries, the files, bytes and SHA-256 of the two builds (hydro registry commit `{_m['hydro_registry_commit'][:12]}`): "
           + ", ".join(f"{k} {v}" for k, v in _m["counts"].items()) + ".", "",
           "| entry | files (project / hydro) | only in project | only in hydro | not hashed by the project build |", "|---|---|---|---|---|"]
    for d in _m["differences"]:
        cv.append(f"| `{d['id']}` | {d.get('project_files', '-')} / {d.get('hydro_files', '-')} | {d.get('only_in_project', '-')} | {d.get('only_in_hydro', '-')} | {', '.join(d.get('project_not_hashed', []))} |")
    cv += ["", "SHA256SUMS entries that do not agree with the file now (the project build uses the SHA256SUMS value; the hydro build hashes the file). "
           "The SHA256SUMS files are not changed:", ""] + [f"- `{x['file']}`: SHA256SUMS {x['sha256_in_SHA256SUMS'][:16]}..., file {x['sha256_of_file'][:16]}..." for x in _m["sha256sums_entries_that_differ_from_the_file"]]
    cv += ["", f"Tracked files under results/hydroacoustics*, coordination/*hydro* and threads/*hydro*: {_m['hydro_tracked_files']}; not in a manifest: {len(_m['hydro_tracked_files_not_in_a_manifest'])}.", ""]
(HERE / "COVERAGE.md").write_text("\n".join(cv) + "\n")
print("INDEX.md and COVERAGE.md written;", sum(tot.values()), "entries")
